include!("parse_helpers.rs");
use nepl3_engine::{analysis::{BindingOptions,region::{*,query::{self as rq,*}},query::{QueryKind,QueryOutcome}},portable::{analysis,region}};
fn main()->Result<(),String>{
 let doc=load("conformance/fixtures/grammar/binding/execution.neplg")?;let mut compiled=nepl3_tools::bootstrap::catalog::compile(&doc,"independent.region-query",&mut budget(),&mut SourceAdmission::default())?;
