 // Literal UTF-8 byte expectations follow lexical scope and independent Foreign roots.
 for (text,offset,expected) in [
  ("let x x apply x x",6,None),
  ("let x x apply x x",16,Some((4,5))),
  ("lambda x lambda x x",18,Some((16,17))),
  ("lambda x guest x",15,None),
  ("lambda x guest lambda x x",24,Some((22,23))),
  ("lambda あ apply あ あ",21,Some((7,10))),
 ] {
 with_completed_input(&compiled,text,|parsed,profile,_,_|{
  let empty=SourceStore::default();let mut a=SourceAdmission::default();let mut c=FoundationCodec::new(profile.registry(),&empty,&mut a).map_err(err)?;
  let keyed=analysis::prepare("independent.region-query",parsed.tree(),BindingOptions,budget().limits(),profile,&mut c,&mut budget()).map_err(err)?;
  let bound=keyed.execute(&mut budget(),&mut SourceAdmission::default()).map_err(err)?;
  let input=region::prepare(&keyed,Some(parsed.reader_facts()),&mut c,&mut budget()).map_err(err)?;
  let src=parsed.tree().bundle.sources.iter().find(|s|s.text()==text).ok_or("source")?.reference();
  let request=RegionQueryRequest{region:RegionRequest{key:input.key(),source:src,offset},kind:QueryKind::Definition};
  let reply=rq::query(&input,&bound,&request,&mut budget(),&mut SourceAdmission::default());
  let RegionQueryOutcome::Complete{region:Some(_),queries}=&reply.outcome else{return Err(format!("{text}: {reply:?}"))};
  assert_eq!(queries.len(),1,"{text}");
  let QueryOutcome::Definition{selection:Some(selection),targets}=&queries[0] else{return Err(format!("{queries:?}"))};
  assert_eq!(selection.span.start(),offset);
  let ranges:Vec<_>=targets.iter().filter_map(|t|t.location.as_ref()?.selection.as_ref()).map(|s|(s.start(),s.end())).collect();
  assert_eq!(ranges,expected.into_iter().collect::<Vec<_>>(),"{text}");
  let packet=NdfValue::List(vec![analysis::request_to_value(&keyed,&mut c,&mut budget()).map_err(err)?,region::sidecar_value(&keyed,Some(parsed.reader_facts()),&mut c,&mut budget()).map_err(err)?,region::query::request_to_value(&request,profile.registry(),&mut c,&mut budget()).map_err(err)?]);
  let bytes=nepl3_wire::encode(&packet,&mut budget()).map_err(err)?;
  let NdfValue::List(ref packet)=nepl3_wire::decode(&bytes,&mut budget()).map_err(err)? else{return Err("packet".into())};
  let receiver_empty=SourceStore::default();let mut ra=SourceAdmission::default();let mut rc=FoundationCodec::new(profile.registry(),&receiver_empty,&mut ra).map_err(err)?;
  let received=analysis::request_decode(&packet[0],profile,&mut rc,&mut budget()).map_err(err)?;
  let prepared=analysis::prepare_received(&received,profile,&mut rc,&mut budget()).map_err(err)?;
  let rebound=prepared.execute(&mut budget(),&mut SourceAdmission::default()).map_err(err)?;
  let facts=region::sidecar_decode(&packet[1],&prepared,&mut rc,&mut budget()).map_err(err)?;
  let region_input=region::prepare(&prepared,facts.as_deref(),&mut rc,&mut budget()).map_err(err)?;
  let rr=region::query::request_decode(&packet[2],profile.registry(),&mut rc,&mut budget()).map_err(err)?;
  let actual=rq::query(&region_input,&rebound,&rr,&mut budget(),&mut SourceAdmission::default());
  assert_eq!(actual.outcome,reply.outcome);assert_eq!(actual.sources,reply.sources);
  let mut refs=request.clone();refs.kind=QueryKind::References(Default::default());let references=rq::query(&input,&bound,&refs,&mut budget(),&mut SourceAdmission::default());let RegionQueryOutcome::Complete{queries,..}=&references.outcome else{return Err("references".into())};assert_eq!(queries.len(),1);let QueryOutcome::References{groups,..}=&queries[0] else{return Err("references variant".into())};let starts=groups.iter().flat_map(|g|&g.locations).map(|l|l.span.start()).collect::<Vec<_>>();let expected_refs=if expected.is_none(){vec![]}else if text.starts_with("let "){vec![14,16]}else if text.contains("あ"){vec![17,21]}else{vec![offset]};assert_eq!(starts,expected_refs);assert_eq!(rq::query(&region_input,&rebound,&refs,&mut budget(),&mut SourceAdmission::default()).outcome,references.outcome);
  if text.contains("あ") {for code in 0..6 {let mut limits=budget().limits();let reason=match code{0=>{limits.work=0;StopReason::WorkLimit},1=>{limits.source_bytes=0;StopReason::SourceLimit},2=>{limits.nodes=0;StopReason::NodeLimit},3=>{limits.allocation_units=0;StopReason::AllocationLimit},4=>{limits.depth=0;StopReason::DepthLimit},_=>StopReason::Cancelled};let mut b=Budget::new(limits);if code==5{b.cancel();}let s=rq::query(&input,&bound,&request,&mut b,&mut SourceAdmission::default());assert_eq!(s.outcome,RegionQueryOutcome::Stopped(reason));assert!(s.sources.is_empty());assert_eq!(s.report.usage,b.usage());assert_eq!(b.poll(),Err(reason));}let mut bad=request.clone();bad.region.offset=22;assert!(matches!(rq::query(&input,&bound,&bad,&mut budget(),&mut SourceAdmission::default()).outcome,RegionQueryOutcome::Invalid(_)));bad.region.offset=24;assert!(matches!(rq::query(&input,&bound,&bad,&mut budget(),&mut SourceAdmission::default()).outcome,RegionQueryOutcome::Complete{region:None,..}));}
  println!("original {text:?} @{offset}: definition {expected:?}, references {expected_refs:?}, fresh CBOR actual binding/query match");
  Ok(())
 })?;
 }
