use nepl3_engine::{analysis::{BindingOptions,rename::*},portable::analysis as keyed};
use nepl3_core::origin::{Mapping,MappingKind};
fn main()->Result<(),String>{
 let doc=load("conformance/fixtures/grammar/binding/execution.neplg")?;let compiled=nepl3_tools::bootstrap::catalog::compile(&doc,"independent.rename-owner",&mut budget(),&mut SourceAdmission::default())?;
 let mut bug=false;
 for inject in [false,true]{with_completed_input(&compiled,"lambda x guest x",|base,profile,_,_|{
  let input=base.tree().bundle.sources.iter().find(|s|s.text()=="lambda x guest x").ok_or("input")?;
  let aux=SourceSnapshot::new(SourceId("guest-only-origin".into()),0,"memory:guest-only-origin".into(),b"x".to_vec(),&mut budget()).map_err(err)?;
  let maps=if inject{vec![Mapping{source:aux.span(0,1).map_err(err)?,target:input.span(7,8).map_err(err)?,kind:MappingKind::Exact}]}else{vec![]};
  let extras=if inject{vec![aux.clone()]}else{vec![]};
  let parsed=parse_completed_with_aux(input,&extras,&maps,profile,&mut budget(),&mut SourceAdmission::default())?;
  assert!(parsed.tree().bundle.source_maps.is_empty());
  let guest=parsed.tree().bundle.nodes.iter().flat_map(|n|&n.fields).find_map(|f|if let nepl3_core::syntax::FieldValue::Foreign(g)=f{Some(g)}else{None}).ok_or("foreign")?;
  assert_eq!(guest.bundle.source_maps.len(),usize::from(inject));
  let empty=SourceStore::default();let mut a=SourceAdmission::default();let mut c=FoundationCodec::new(profile.registry(),&empty,&mut a).map_err(err)?;
  let old=keyed::prepare("independent.rename-owner",parsed.tree(),BindingOptions,budget().limits(),profile,&mut c,&mut budget()).map_err(err)?;let bound=old.execute(&mut budget(),&mut SourceAdmission::default()).map_err(err)?;
  println!("inject={inject}, actual sealed parser host maps {}, guest maps {}, flat maps {}",parsed.tree().bundle.source_maps.len(),guest.bundle.source_maps.len(),bound.reply().source_maps().len());
  let request=RenameRequest{key:old.key(),source:input.reference(),offset:7,new_name:"z".into(),writable:vec![if inject{aux.reference()}else{input.reference()}]};
  let mut b=budget();let mut draft=match prepare(&parsed,&old,&bound,&request,&mut b){Ok(d)=>d,Err(e)=>{println!("inject={inject} prepare rejected: {e:?}");if inject{return Ok(());}return Err(format!("control: {e:?}"));}};
  let (changed,new_aux)=draft.with_operation(|sources,_,_|(sources.latest(&input.identity().source).cloned(),sources.latest(&aux.identity().source).cloned()));
  let changed=changed.ok_or("changed primary")?;assert_eq!(changed.text(),"lambda z guest x");
  let new_maps=if inject{let aux=new_aux.as_ref().ok_or("new aux")?;assert_eq!(aux.text(),"z");vec![Mapping{source:aux.span(0,1).map_err(err)?,target:changed.span(7,8).map_err(err)?,kind:MappingKind::Exact}]}else{vec![]};
  let new_extras=new_aux.into_iter().collect::<Vec<_>>();
  let next_parse=draft.with_operation(|_,b,a|parse_completed_with_aux(&changed,&new_extras,&new_maps,profile,b,a))?;
  let (next,next_bound)=draft.with_operation(|sources,b,a|->Result<_,String>{let mut c=FoundationCodec::new(profile.registry(),sources,a).map_err(err)?;let next=keyed::prepare("independent.rename-owner",next_parse.tree(),BindingOptions,b.limits(),profile,&mut c,b).map_err(err)?;let bound=next.execute(b,a).map_err(err)?;Ok((next,bound))})?;
  let reply=draft.accept(&next_parse,&next,&next_bound);println!("inject={inject}, actual accept: {:?}",reply.outcome);
  if let RenameOutcome::Complete{edits,..}=reply.outcome{assert_eq!(edits.len(),1);if inject{assert_eq!(edits[0].span.snapshot_ref().source,aux.identity().source);bug=true;println!("BUG: guest-only map authorized writable aux as host declaration rename root");}else{assert_eq!(edits[0].span.snapshot_ref().source,input.identity().source);}}else if !inject{return Err("control completion".into());}
  Ok(())
 })?;}
 if bug{return Err("owner-local rename expectation failed".into());}Ok(())
}
