use nepl3_core::{
    facts::*,
    syntax::{Environment, EnvironmentEntry},
    value::NdfValue,
    value_codec::FoundationValueCodec,
};
use nepl3_engine::{binding::*, parse::*, profile::*, tree::ValidatedParseTree};
use nepl3_reader::{
    model::{ProviderCall, ReadRequest, ReaderContext},
    runtime::ProviderReply,
};
use nepl3_wire::{environment::environment_digest, foundation::FoundationCodec};
fn err(v: impl std::fmt::Debug) -> String {
    format!("{v:?}")
}
fn with_input<T>(
    compiled: &CompiledLanguage,
    input: &str,
    finish: impl FnOnce(
        &ValidatedParseTree<'_>,
        &ResolvedParseProfile<'_>,
        &mut Budget,
        &mut SourceAdmission,
    ) -> Result<T, String>,
) -> Result<T, String> {
    with_completed_input(compiled, input, |parsed, profile, b, a| {
        let checked = parsed.tree().validate(profile, b, a).map_err(err)?;
        finish(&checked, profile, b, a)
    })
}
fn with_completed_input<T>(
    compiled: &CompiledLanguage,
    input: &str,
    finish: impl FnOnce(
        &CompletedParse,
        &ResolvedParseProfile<'_>,
        &mut Budget,
        &mut SourceAdmission,
    ) -> Result<T, String>,
) -> Result<T, String> {
    with_completed_input_extra(compiled, None, input, finish)
}
fn with_completed_input_extra<T>(
    compiled: &CompiledLanguage,
    extra: Option<&nepl3_engine::package::LanguagePackage>,
    input: &str,
    finish: impl FnOnce(
        &CompletedParse,
        &ResolvedParseProfile<'_>,
        &mut Budget,
        &mut SourceAdmission,
    ) -> Result<T, String>,
) -> Result<T, String> {
    let p = &compiled.package;
    let r = &compiled.registry;
    let identity = p
        .check(r, &mut budget())
        .and_then(|v| v.semantic_identity(&mut budget()))
        .map_err(err)?;
    // This fixture registers the exact source of its host adapter implementation.
    let implementation = Digest::of(b"independent-rename-fixture");
    let implementation_for = |operation: &nepl3_core::value::OperationRef| {
        if operation.name == "bindingFacts" {
            implementation
        } else {
            implementation
        }
    };
    let mut operations = Vec::new();
    for operation in p
        .reader
        .providers
        .iter()
        .map(|v| &v.operation)
        .chain(p.extensions.iter().map(|v| &v.operation))
    {
        if !operations.contains(operation) {
            operations.push(operation.clone());
        }
    }
    let providers: Vec<_> = operations
        .iter()
        .map(|operation| ProviderImplementation {
            provider: operation.name.clone(),
            revision: 1,
            implementation_digest: implementation_for(operation),
            operations: vec![operation.clone()],
        })
        .collect();
    let requirements = operations
        .iter()
        .map(|operation| ProviderRequirement {
            provider: operation.name.clone(),
            revision: 1,
            implementation_digest: implementation_for(operation),
            operation: operation.clone(),
        })
        .collect();
    let mut schemas = vec![p.schema.clone()];
    for schema in p.payload_schemas.iter().chain(
        ["nepl3.foundation", "nepl3.reader", "nepl3.engine"]
            .iter()
            .filter_map(|name| r.selected(name, 1)),
    ) {
        if !schemas.contains(schema) {
            schemas.push(schema.clone());
        }
    }
    let mut languages = vec![LanguageRegistration {
        alias: "B".into(),
        package: identity,
        default_category: "Expr".into(),
    }];
    let mut packages = vec![p];
    if let Some(extra) = extra {
        schemas.push(extra.schema.clone());
        languages.push(LanguageRegistration {
            alias: "Other".into(),
            package: extra
                .check(r, &mut budget())
                .and_then(|v| v.semantic_identity(&mut budget()))
                .map_err(err)?,
            default_category: "Expr".into(),
        });
        packages.push(extra);
    }
    let profile = ParseProfile {
        id: "binding-review".into(),
        languages,
        schemas,
        head_providers: vec![],
        category_modes: vec![],
        providers: requirements,
        allowlist: operations,
        resources: vec![],
        limits: budget().limits(),
    };
    let resolved = profile
        .resolve(
            &RuntimeCatalog {
                packages: &packages,
                providers: &providers,
                resources: &[],
            },
            r,
            &mut budget(),
        )
        .map_err(err)?;
    let mut b = budget();
    let mut a = SourceAdmission::default();
    let source = SourceSnapshot::new(
        SourceId("binding-input".into()),
        0,
        "memory:binding-input".into(),
        input.as_bytes().to_vec(),
        &mut b,
    )
    .map_err(err)?;
    let parsed = parse_completed(&source, &resolved, &mut b, &mut a)?;
    finish(&parsed, &resolved, &mut b, &mut a)
}

fn parse_completed(
    source: &SourceSnapshot,
    resolved: &ResolvedParseProfile<'_>,
    b: &mut Budget,
    a: &mut SourceAdmission,
) -> Result<CompletedParse, String> {
    parse_completed_with_aux(source, &[], &[], resolved, b, a)
}
fn parse_completed_with_aux(
    source: &SourceSnapshot,
    extras: &[SourceSnapshot],
    maps: &[nepl3_core::origin::Mapping],
    resolved: &ResolvedParseProfile<'_>,
    b: &mut Budget,
    a: &mut SourceAdmission,
) -> Result<CompletedParse, String> {
    let r = resolved.registry();
    let p = resolved.language("B", b).map_err(err)?;
    let foundation = r.selected("nepl3.foundation", 1).ok_or("foundation")?;
    let mut store = SourceStore::default();
    store.insert(source.clone()).map_err(err)?;
    for source in extras {
        store.insert(source.clone()).map_err(err)?;
    }
    let value = Environment {
        bindings: vec![],
        resources: vec![],
    };
    let digest = environment_digest(&value, foundation, r, b).map_err(err)?;
    let raw = ReaderContext {
        schema: p.schema.clone(),
        category: "Expr".into(),
        mode: "Code".into(),
        origins: extras
            .iter()
            .map(|v| {
                v.span(0, v.text().len() as u64)
                    .map(nepl3_core::origin::Origin::Direct)
            })
            .collect::<Result<_, _>>()
            .map_err(err)?,
        environment: EnvironmentEntry {
            id: 0,
            digest,
            value,
        },
    };
    let mut raws = vec![raw];
    for language in &resolved.profile().languages {
        if language.alias == "B" {
            continue;
        }
        let p = resolved.language(&language.alias, b).map_err(err)?;
        let mut raw = raws[0].clone();
        raw.schema = p.schema.clone();
        raw.category = language.default_category.clone();
        raws.push(raw);
    }
    let environments = {
        let mut codec = FoundationCodec::new(r, &store, a).map_err(err)?;
        let proofs = raws
            .iter()
            .map(|raw| raw.check(&mut codec, &store, r, b).map_err(err))
            .collect::<Result<Vec<_>, _>>()?;
        let inputs = resolved
            .profile()
            .languages
            .iter()
            .zip(&proofs)
            .map(|(language, proof)| EnvironmentInput {
                alias: &language.alias,
                context: proof,
            })
            .collect::<Vec<_>>();
        ParseEnvironmentSet::prepare(resolved, &inputs, &store, &mut codec, b).map_err(err)?
    };
    let entry = resolved.entry("B", None, b).map_err(err)?;
    let states = resolved
        .profile()
        .languages
        .iter()
        .map(|v| LanguageReaderState {
            alias: v.alias.clone(),
            state: NdfValue::Unit,
        })
        .collect::<Vec<_>>();
    let mut parser =
        ParseSession::new("binding-parse".into(), resolved, &environments, b).map_err(err)?;
    let mut result = parser
        .read_completed(
            ParseRequest {
                snapshot: source,
                start: 0,
                limit: source.text().len() as u64,
                final_input: true,
                entry: &entry,
                states: &states,
            },
            &store,
            b,
            a,
        )
        .map_err(err)?;
    let mut reservations = 0;
    let mut additional = false;
    loop {
        let progress = match result {
            ParseCompletion::Continue(parsed) => {
                assert_eq!(parsed.cursor(), source.text().len() as u64);
                return Ok(parsed);
            }
            ParseCompletion::Break(reply) => reply,
        };
        match progress.outcome {
            ParseOutcome::Await { call, continuation } => {
                let ProviderCall::Read {
                    operation,
                    request,
                    depth_base,
                    ..
                } = call.as_ref()
                else {
                    return Err("unexpected provider".into());
                };
                let mut declared = SourceStore::default();
                for source in &request.sources {
                    declared.insert(source.clone()).map_err(err)?;
                }
                let snapshot = declared
                    .resolve(&request.snapshot)
                    .ok_or("request source")?;
                let mut terminal = b
                    .with_depth_at_least(*depth_base, |b| {
                        let mut codec = FoundationCodec::new(r, &declared, a)
                            .map_err(|_| nepl3_reader::runtime::ReaderError::Context)?;
                        let checked = request
                            .context
                            .check(&mut codec, &declared, r, b)
                            .map_err(|_| nepl3_reader::runtime::ReaderError::Context)?;
                        nepl3_reader::builtin::provider::read(
                            operation,
                            ReadRequest {
                                snapshot,
                                start: request.start,
                                limit: request.limit,
                                final_input: request.final_input,
                                context: &checked,
                                state: &request.state,
                            },
                            r,
                            &declared,
                            b,
                            a,
                        )
                    })
                    .map_err(err)?;
                if !additional && request.start == 15
                    && let nepl3_reader::model::ReadReply::Matched {
                        sources,
                        source_maps,
                        ..
                    } = &mut terminal
                {
                    for source in extras {
                        if !sources.iter().any(|v| v.identity() == source.identity()) {
                            sources.push(source.clone());
                        }
                    }
                    source_maps.extend_from_slice(maps);
                    additional = true;
                }
                result = parser
                    .resume_completed(
                        &continuation,
                        ProviderReply::Read(Box::new(terminal)),
                        &store,
                        b,
                        a,
                    )
                    .map_err(err)?;
            }
            ParseOutcome::Reserve { continuation, .. } => {
                reservations += 1;
                let reserved = SourceReservation {
                    source_id: SourceId(format!("decoded-{reservations}")),
                    revision: 0,
                    uri: format!("memory:decoded-{reservations}"),
                };
                result = parser
                    .reserve_completed(&continuation, &reserved, &store, b, a)
                    .map_err(err)?;
            }
            other => return Err(format!("candidate: {other:?}")),
        }
    }
}





use nepl3_engine::{analysis::{BindingOptions,rename::*},portable::analysis as keyed};
use nepl3_core::origin::{Mapping,MappingKind};
fn main()->Result<(),String>{
 let doc=load("conformance/fixtures/grammar/binding/execution.neplg")?;let compiled=nepl3_tools::bootstrap::catalog::compile(&doc,"independent.rename-owner",&mut budget(),&mut SourceAdmission::default())?;
 let mut bug=false;
 for inject in [false,true]{with_completed_input(&compiled,"lambda x guest x",|base,profile,_,_|{
  let input=base.tree().bundle.sources.iter().find(|s|s.text()=="lambda x guest x").ok_or("input")?;
  let aux=SourceSnapshot::new(SourceId("guest-only-origin".into()),0,"memory:guest-only-origin".into(),b"x".to_vec(),&mut budget()).map_err(err)?;
  let maps=if inject{vec![Mapping{source:aux.span(0,1).map_err(err)?,target:input.span(7,8).map_err(err)?,kind:MappingKind::Exact}]}else{vec![]};
  let extras=if inject{vec![aux.clone()]}else{vec![]};
  let parsed=parse_completed_with_aux(input,&extras,&maps,profile,&mut budget(),&mut SourceAdmission::default())?;
  assert!(parsed.tree().bundle.source_maps.is_empty());
  let guest=parsed.tree().bundle.nodes.iter().flat_map(|n|&n.fields).find_map(|f|if let nepl3_core::syntax::FieldValue::Foreign(g)=f{Some(g)}else{None}).ok_or("foreign")?;
  assert_eq!(guest.bundle.source_maps.len(),usize::from(inject));
  let empty=SourceStore::default();let mut a=SourceAdmission::default();let mut c=FoundationCodec::new(profile.registry(),&empty,&mut a).map_err(err)?;
  let old=keyed::prepare("independent.rename-owner",parsed.tree(),BindingOptions,budget().limits(),profile,&mut c,&mut budget()).map_err(err)?;let bound=old.execute(&mut budget(),&mut SourceAdmission::default()).map_err(err)?;
  println!("inject={inject}, actual sealed parser host maps {}, guest maps {}, flat maps {}",parsed.tree().bundle.source_maps.len(),guest.bundle.source_maps.len(),bound.reply().source_maps().len());
  let request=RenameRequest{key:old.key(),source:input.reference(),offset:7,new_name:"z".into(),writable:vec![if inject{aux.reference()}else{input.reference()}]};
  let mut b=budget();let mut draft=match prepare(&parsed,&old,&bound,&request,&mut b){Ok(d)=>d,Err(e)=>{println!("inject={inject} prepare rejected: {e:?}");if inject{return Ok(());}return Err(format!("control: {e:?}"));}};
  let (changed,new_aux)=draft.with_operation(|sources,_,_|(sources.latest(&input.identity().source).cloned(),sources.latest(&aux.identity().source).cloned()));
  let changed=changed.ok_or("changed primary")?;assert_eq!(changed.text(),"lambda z guest x");
  let new_maps=if inject{let aux=new_aux.as_ref().ok_or("new aux")?;assert_eq!(aux.text(),"z");vec![Mapping{source:aux.span(0,1).map_err(err)?,target:changed.span(7,8).map_err(err)?,kind:MappingKind::Exact}]}else{vec![]};
  let new_extras=new_aux.into_iter().collect::<Vec<_>>();
  let next_parse=draft.with_operation(|_,b,a|parse_completed_with_aux(&changed,&new_extras,&new_maps,profile,b,a))?;
  let (next,next_bound)=draft.with_operation(|sources,b,a|->Result<_,String>{let mut c=FoundationCodec::new(profile.registry(),sources,a).map_err(err)?;let next=keyed::prepare("independent.rename-owner",next_parse.tree(),BindingOptions,b.limits(),profile,&mut c,b).map_err(err)?;let bound=next.execute(b,a).map_err(err)?;Ok((next,bound))})?;
  let reply=draft.accept(&next_parse,&next,&next_bound);println!("inject={inject}, actual accept: {:?}",reply.outcome);
  if let RenameOutcome::Complete{edits,..}=reply.outcome{assert_eq!(edits.len(),1);if inject{assert_eq!(edits[0].span.snapshot_ref().source,aux.identity().source);bug=true;println!("BUG: guest-only map authorized writable aux as host declaration rename root");}else{assert_eq!(edits[0].span.snapshot_ref().source,input.identity().source);}}else if !inject{return Err("control completion".into());}
  Ok(())
 })?;}
 if bug{return Err("owner-local rename expectation failed".into());}Ok(())
}

