//! Budgeted exact coverage, independent of how a correspondence is segmented.
use super::*;
use nepl3_core::origin::Mapping;

pub(super) fn project(
    span: &Span,
    maps: &[Mapping],
    sources: &[SourceSnapshot],
    reverse: bool,
    b: &mut Budget,
) -> Result<Vec<Span>, RenameError> {
    // One group represents a single snapshot and constant byte displacement.
    // Forward projection may have several outputs; inverse callers require one.
    let mut groups: Vec<(&Span, i128)> = Vec::new();
    for map in maps {
        let (from, to) = sides(map, reverse);
        if !same_source(span.snapshot_ref(), from.snapshot_ref(), b)?
            || from.start() >= span.end()
            || span.start() >= from.end()
        {
            continue;
        }
        if map.kind != MappingKind::Exact {
            return Err(RenameError::RenameNotInvertible);
        }
        let offset = i128::from(to.start()) - i128::from(from.start());
        let mut known = false;
        for (other, delta) in &groups {
            if same_source(other.snapshot_ref(), to.snapshot_ref(), b)? && *delta == offset {
                known = true;
            }
        }
        if !known {
            push(&mut groups, (to, offset), b)?;
        }
    }
    let mut result = Vec::new();
    for (target, offset) in groups {
        let mut cursor = span.start();
        while cursor < span.end() {
            let mut next = cursor;
            for map in maps {
                let (from, to) = sides(map, reverse);
                if !same_source(span.snapshot_ref(), from.snapshot_ref(), b)?
                    || !same_source(target.snapshot_ref(), to.snapshot_ref(), b)?
                    || map.kind != MappingKind::Exact
                    || i128::from(to.start()) - i128::from(from.start()) != offset
                {
                    continue;
                }
                if from.start() <= cursor && cursor < from.end() {
                    next = next.max(from.end().min(span.end()));
                }
            }
            if next == cursor {
                return Err(RenameError::RenameNotInvertible);
            }
            cursor = next;
        }
        let mut snapshot = None;
        for source in sources {
            if same_source(source.identity(), target.snapshot_ref(), b)? {
                snapshot = Some(source);
                break;
            }
        }
        let snapshot = snapshot.ok_or(SourceError::MissingSnapshot)?;
        let start = u64::try_from(i128::from(span.start()) + offset)
            .map_err(|_| RenameError::RenameNotInvertible)?;
        let end = u64::try_from(i128::from(span.end()) + offset)
            .map_err(|_| RenameError::RenameNotInvertible)?;
        push(&mut result, snapshot.span_with_budget(start, end, b)?, b)?;
    }
    Ok(result)
}
fn sides(map: &Mapping, reverse: bool) -> (&Span, &Span) {
    if reverse {
        (&map.target, &map.source)
    } else {
        (&map.source, &map.target)
    }
}

use super::*;
pub(super) fn prepare<'a, 'tree, 'profile, 'budget>(
    original: &'a PreparedBindingRequest<'tree, 'profile>,
    binding: &'a BoundBindingReply,
    request: &'a RenameRequest,
    budget: &'budget mut Budget,
) -> Result<RenameDraft<'a, 'tree, 'profile, 'budget>, RenameError> {
    budget.poll()?;
    request.validate_identity(budget)?;
    if original.key != request.key || binding.key() != request.key {
        return Err(RenameError::RequestMismatch);
    }
    if budget.limits() != original.limits {
        return Err(BindingAccessError::LimitsMismatch.into());
    }
    budget.charge(Resource::Work, request.new_name.len() as u64)?;
    if request.new_name.is_empty() {
        return Err(RenameError::InvalidName);
    }
    let analysis = binding.for_source(&request.key, &request.source, budget)?;
    let facts = analysis.facts();
    let mut sources = SourceStore::default();
    let mut admission = SourceAdmission::default();
    for source in binding.reply().sources() {
        admission.admit_existing(source, budget)?;
        for prior in sources.snapshots() {
            budget.charge(
                Resource::Work,
                (prior.identity().source.0.len() + source.identity().source.0.len()) as u64 + 42,
            )?;
        }
        sources.insert(source.clone_with_budget(budget)?)?;
    }
    let source = sources
        .resolve(&request.source)
        .ok_or(SourceError::MissingSnapshot)?;
    source.check_range(request.offset, request.offset)?;
    let mut selected: Option<&nepl3_core::facts::Occurrence> = None;
    for occurrence in &facts.occurrences {
        budget.charge(Resource::Nodes, 1)?;
        if same_source(occurrence.span.snapshot_ref(), source.identity(), budget)?
            && occurrence.span.start() <= request.offset
            && request.offset < occurrence.span.end()
            && selected.is_none_or(|v| {
                occurrence.span.end() - occurrence.span.start() < v.span.end() - v.span.start()
            })
        {
            selected = Some(occurrence);
        }
    }
    let entity = match &selected.ok_or(RenameError::NoOccurrence)?.resolution {
        ReferenceResolution::Resolved(id) => *id,
        ReferenceResolution::Ambiguous(_) => return Err(RenameError::Ambiguous),
        ReferenceResolution::Unresolved(_) => return Err(RenameError::Unresolved),
        ReferenceResolution::Deferred(_) => return Err(RenameError::Deferred),
    };
    budget.charge(Resource::Work, facts.entities.len() as u64)?;
    let target = facts
        .entities
        .iter()
        .find(|v| v.id == entity)
        .ok_or(RenameError::RequestMismatch)?;
    if target.selection.is_none() {
        return Err(RenameError::NoLocation);
    }
    let namespace = facts
        .namespaces
        .get(target.namespace.0 as usize)
        .ok_or(RenameError::RequestMismatch)?;
    for registration in &original.profile.profile().languages {
        let package = original
            .profile
            .language(&registration.alias, budget)
            .map_err(|error| match error {
                crate::profile::ProfileError::Stopped(reason) => RenameError::Stopped(reason),
                _ => RenameError::RequestMismatch,
            })?;
        budget.charge(
            Resource::Work,
            (namespace.schema.package.len() + package.schema.package.len()) as u64 + 42,
        )?;
        if namespace.schema != package.schema {
            continue;
        }
        for form in &package.forms {
            budget.charge(
                Resource::Work,
                (form.spelling.len() + request.new_name.len()) as u64,
            )?;
            if form.spelling == request.new_name {
                return Err(RenameError::InvalidName);
            }
        }
    }
    let mut edits = Vec::new();
    for occurrence in &facts.occurrences {
        budget.charge(Resource::Work, 1)?;
        match &occurrence.resolution {
            ReferenceResolution::Ambiguous(ids) => {
                budget.charge(Resource::Work, ids.len() as u64)?;
                if ids.contains(&entity) {
                    return Err(RenameError::Ambiguous);
                }
            }
            ReferenceResolution::Resolved(id) if *id == entity => {
                if let Some(id) = occurrence.origin {
                    budget.charge(Resource::Work, 1)?;
                    if matches!(
                        facts.origins.get(id.0 as usize),
                        Some(Origin::Composite(_) | Origin::Synthetic { .. }) | None
                    ) {
                        return Err(RenameError::RenameNotInvertible);
                    }
                }
                add_edit(
                    &occurrence.span,
                    &occurrence.name,
                    facts,
                    request,
                    &sources,
                    &mut edits,
                    budget,
                )?;
            }
            _ => {}
        }
    }
    // A declared entity name must be editable even when a custom provider does
    // not also issue a Definition occurrence.
    add_edit(
        target.selection.as_ref().ok_or(RenameError::NoLocation)?,
        &target.name,
        facts,
        request,
        &sources,
        &mut edits,
        budget,
    )?;
    for i in 1..edits.len() {
        let mut j = i;
        while j > 0 {
            let a = &edits[j - 1].span;
            let c = &edits[j].span;
            budget.charge(
                Resource::Work,
                (a.snapshot_ref().source.0.len() + c.snapshot_ref().source.0.len()) as u64 + 42,
            )?;
            if (&a.snapshot_ref().source.0, a.start(), a.end())
                <= (&c.snapshot_ref().source.0, c.start(), c.end())
            {
                break;
            }
            edits.swap(j - 1, j);
            j -= 1;
        }
    }
    // Exact derived snapshots are part of the candidate, too. Apply explicit
    // internal edits while preserving every unmapped byte; only writable root
    // edits are eventually advertised to the editor.
    let candidates = derived_edits(&edits, facts, &sources, budget)?;
    sources.apply(&candidates, budget, &mut admission)?;
    Ok(RenameDraft {
        original,
        binding,
        request,
        entity,
        edits,
        candidate_edits: candidates,
        sources,
        admission,
        budget,
    })
}
fn derived_edits(
    edits: &[TextEdit],
    facts: &FactSet,
    sources: &SourceStore,
    b: &mut Budget,
) -> Result<Vec<TextEdit>, RenameError> {
    let mut out = Vec::new();
    let mut depths = Vec::new();
    for edit in edits {
        push(
            &mut out,
            TextEdit {
                span: copy_span(&edit.span, b)?,
                expected_digest: edit.expected_digest,
                replacement: text(&edit.replacement, b)?,
            },
            b,
        )?;
        push(&mut depths, 1u64, b)?;
    }
    let mut index = 0;
    while index < out.len() {
        b.observe_depth(depths[index])?;
        let projected = super::mapping::project(
            &out[index].span,
            &facts.source_maps,
            &facts.sources,
            false,
            b,
        )?;
        for span in projected {
            let source = sources
                .get_ref(span.snapshot_ref())
                .ok_or(SourceError::MissingSnapshot)?;
            let mut known = false;
            for prior in &out {
                if same_source(prior.span.snapshot_ref(), span.snapshot_ref(), b)?
                    && prior.span.start() == span.start()
                    && prior.span.end() == span.end()
                {
                    known = true;
                }
            }
            if known {
                continue;
            }
            let old = source.slice(&span)?;
            b.charge(Resource::Work, old.len() as u64)?;
            let value = TextEdit {
                span,
                expected_digest: Digest::of(old.as_bytes()),
                replacement: text(&out[index].replacement, b)?,
            };
            push(&mut out, value, b)?;
            let depth = depths[index].checked_add(1).ok_or(StopReason::DepthLimit)?;
            push(&mut depths, depth, b)?;
        }
        index += 1;
    }
    Ok(out)
}
fn add_edit(
    span: &Span,
    name: &str,
    facts: &FactSet,
    request: &RenameRequest,
    sources: &SourceStore,
    edits: &mut Vec<TextEdit>,
    b: &mut Budget,
) -> Result<(), RenameError> {
    let span = inverse(span, facts, &request.writable, b)?;
    let old = sources
        .get_ref(span.snapshot_ref())
        .ok_or(SourceError::MissingSnapshot)?
        .slice(&span)?;
    b.charge(Resource::Work, (old.len() + name.len()) as u64)?;
    // Replacement of an encoded spelling needs a declared inverse encoder.
    // Equal decoded names do not authorize dropping quotes or escape syntax.
    if old != name {
        return Err(RenameError::RenameNotInvertible);
    }
    for prior in edits.iter() {
        if same_source(prior.span.snapshot_ref(), span.snapshot_ref(), b)?
            && prior.span.start() == span.start()
            && prior.span.end() == span.end()
        {
            return Ok(());
        }
    }
    b.charge(Resource::Work, old.len() as u64)?;
    push(
        edits,
        TextEdit {
            expected_digest: Digest::of(old.as_bytes()),
            span,
            replacement: text(&request.new_name, b)?,
        },
        b,
    )
}
fn inverse(
    span: &Span,
    facts: &FactSet,
    writable: &[SourceRef],
    b: &mut Budget,
) -> Result<Span, RenameError> {
    let mut current = copy_span(span, b)?;
    let mut visited = Vec::new();
    loop {
        b.observe_depth(visited.len() as u64 + 1)?;
        b.charge(Resource::Nodes, 1)?;
        for seen in &visited {
            let seen: &Span = seen;
            if same_source(seen.snapshot_ref(), current.snapshot_ref(), b)?
                && seen.start() == current.start()
                && seen.end() == current.end()
            {
                return Err(OriginError::Cycle.into());
            }
        }
        push(&mut visited, copy_span(&current, b)?, b)?;
        let mut projected =
            super::mapping::project(&current, &facts.source_maps, &facts.sources, true, b)?;
        if projected.len() > 1 {
            return Err(RenameError::RenameNotInvertible);
        }
        if let Some(next) = projected.pop() {
            current = next;
            continue;
        }
        for allowed in writable {
            b.charge(
                Resource::Work,
                (allowed.source_id.0.len() + current.snapshot_ref().source.0.len()) as u64 + 42,
            )?;
            if allowed.source_id == current.snapshot_ref().source
                && allowed.revision == current.snapshot_ref().revision
                && allowed.digest == current.snapshot_ref().digest
            {
                return Ok(current);
            }
        }
        return Err(RenameError::NotWritable);
    }
}

use super::*;
use crate::{
    recovery::ParseTree,
    selection::{BundleContext, ShapeSelection},
};
use nepl3_core::{
    syntax::{FieldValue, SyntaxBundle, canonical::BundleMappings},
    value::{NdfScalar, NdfValue},
};
fn canonical(error: nepl3_core::syntax::canonical::CanonicalError) -> RenameError {
    match error {
        nepl3_core::syntax::canonical::CanonicalError::Stopped(r) => RenameError::Stopped(r),
        _ => RenameError::ShapeChanged,
    }
}
pub(super) fn check(
    d: &mut RenameDraft<'_, '_, '_, '_>,
    p: &PreparedBindingRequest<'_, '_>,
    old: &FactSet,
    new: &FactSet,
) -> Result<(), RenameError> {
    let a = BundleMappings::new(&d.original.tree.tree().bundle, d.budget).map_err(canonical)?;
    let c = BundleMappings::new(&p.tree.tree().bundle, d.budget).map_err(canonical)?;
    if a.entries().len() != c.entries().len() {
        return Err(RenameError::ShapeChanged);
    }
    for (a, c) in a.entries().iter().zip(c.entries()) {
        let ab = a.bundle();
        let cb = c.bundle();
        if a.order().len() != c.order().len() || ab.environments.len() != cb.environments.len() {
            return Err(RenameError::ShapeChanged);
        }
        for (a, c) in ab.environments.iter().zip(&cb.environments) {
            d.budget.charge(Resource::Work, 42)?;
            if a.id != c.id || a.digest != c.digest {
                return Err(RenameError::ShapeChanged);
            }
        }
        let ac = context(
            d.original.tree.tree(),
            ab,
            d.original.profile.registry(),
            d.budget,
        )?;
        let cc = context(p.tree.tree(), cb, p.profile.registry(), d.budget)?;
        for (ai, ci) in a.order().iter().zip(c.order()) {
            d.budget.charge(Resource::Nodes, 1)?;
            let an = &ab.nodes[*ai];
            let cn = &cb.nodes[*ci];
            d.budget.charge(
                Resource::Work,
                (an.schema.package.len() + cn.schema.package.len() + an.kind.len() + cn.kind.len())
                    as u64
                    + 42,
            )?;
            if an.schema != cn.schema || an.kind != cn.kind || an.fields.len() != cn.fields.len() {
                return Err(RenameError::ShapeChanged);
            }
            for (a, c) in [(&an.head, &cn.head), (&an.cover, &cn.cover)] {
                match (a, c) {
                    (Some(a), Some(c)) if super::verify::spans(d, old, new, a, c)? => {}
                    (None, None) => {}
                    _ => return Err(RenameError::ShapeChanged),
                }
            }
            d.budget
                .charge(Resource::Work, (ac.nodes.len() + cc.nodes.len()) as u64)?;
            let av = ac
                .nodes
                .iter()
                .find(|v| v.node.0 == *ai as u64)
                .ok_or(RenameError::ShapeChanged)?;
            let cv = cc
                .nodes
                .iter()
                .find(|v| v.node.0 == *ci as u64)
                .ok_or(RenameError::ShapeChanged)?;
            d.budget.charge(
                Resource::Work,
                (av.entry.alias.len()
                    + cv.entry.alias.len()
                    + av.entry.category.len()
                    + cv.entry.category.len()
                    + av.entry.mode.len()
                    + cv.entry.mode.len()) as u64
                    + 42,
            )?;
            if av.entry != cv.entry
                || av.execution_digest != cv.execution_digest
                || !selection(&av.shape, &cv.shape, d.budget)?
            {
                return Err(RenameError::ShapeChanged);
            }
            let edited = an
                .head
                .as_ref()
                .map(|span| is_edit(d, span))
                .transpose()?
                .unwrap_or(false);
            for (af, cf) in an.fields.iter().zip(&cn.fields) {
                let same = match (af, cf) {
                    (FieldValue::Child(x), FieldValue::Child(y)) => {
                        a.mapped(*x).map_err(canonical)? == c.mapped(*y).map_err(canonical)?
                    }
                    (FieldValue::Children(x), FieldValue::Children(y)) => {
                        if x.len() != y.len() {
                            return Err(RenameError::ShapeChanged);
                        }
                        for (x, y) in x.iter().zip(y) {
                            d.budget.charge(Resource::Work, 1)?;
                            if a.mapped(*x).map_err(canonical)?
                                != c.mapped(*y).map_err(canonical)?
                            {
                                return Err(RenameError::ShapeChanged);
                            }
                        }
                        true
                    }
                    (FieldValue::Foreign(x), FieldValue::Foreign(y)) => {
                        d.budget.charge(
                            Resource::Work,
                            (x.schema.package.len()
                                + y.schema.package.len()
                                + x.category.len()
                                + y.category.len()) as u64
                                + 84,
                        )?;
                        x.schema == y.schema
                            && x.category == y.category
                            && x.environment == y.environment
                    }
                    (FieldValue::Atom(x), FieldValue::Atom(y)) => {
                        atom(x, y, edited, &d.request.new_name, d.budget)?
                    }
                    _ => false,
                };
                if !same {
                    return Err(RenameError::ShapeChanged);
                }
            }
            match (an.token, cn.token) {
                (Some(x), Some(y)) => {
                    let x = ab
                        .tokens
                        .get(x.0 as usize)
                        .ok_or(RenameError::ShapeChanged)?;
                    let y = cb
                        .tokens
                        .get(y.0 as usize)
                        .ok_or(RenameError::ShapeChanged)?;
                    d.budget.charge(
                        Resource::Work,
                        (x.kind.schema.package.len() + y.kind.schema.package.len()) as u64 + 42,
                    )?;
                    if x.kind != y.kind || !super::verify::spans(d, old, new, &x.head, &y.head)? {
                        return Err(RenameError::ShapeChanged);
                    }
                    if let NdfValue::Text(value) = &y.payload {
                        d.budget.charge(
                            Resource::Work,
                            (value.len() + d.request.new_name.len()) as u64,
                        )?;
                    }
                    let renamed = edited
                        && matches!((&x.payload,&y.payload),(NdfValue::Text(_),NdfValue::Text(value)) if value==&d.request.new_name);
                    if !renamed && !x.payload.equal_with_budget(&y.payload, d.budget)? {
                        return Err(RenameError::ShapeChanged);
                    }
                }
                (None, None) => {}
                _ => return Err(RenameError::ShapeChanged),
            }
        }
    }
    Ok(())
}
fn context<'a>(
    tree: &'a ParseTree,
    bundle: &SyntaxBundle,
    registry: &nepl3_core::schema::SchemaRegistry,
    b: &mut Budget,
) -> Result<&'a BundleContext, RenameError> {
    for context in &tree.contexts {
        let owner =
            crate::tree::path(&tree.bundle, &context.path, registry, b).map_err(|e| match e {
                crate::tree::TreeError::Stopped(r) => RenameError::Stopped(r),
                _ => RenameError::ShapeChanged,
            })?;
        if core::ptr::eq(owner, bundle) {
            return Ok(context);
        }
    }
    Err(RenameError::ShapeChanged)
}
fn selection(a: &ShapeSelection, c: &ShapeSelection, b: &mut Budget) -> Result<bool, RenameError> {
    b.charge(Resource::Work, 1)?;
    Ok(match (a, c) {
        (ShapeSelection::Form { index: a }, ShapeSelection::Form { index: c })
        | (ShapeSelection::Leaf { index: a }, ShapeSelection::Leaf { index: c }) => a == c,
        (ShapeSelection::Builtin { read: a }, ShapeSelection::Builtin { read: c }) => a == c,
        (ShapeSelection::List { read: a, cons: x }, ShapeSelection::List { read: c, cons: y }) => {
            a == c && x == y
        }
        (
            ShapeSelection::Dynamic {
                provider: a,
                shape: x,
                child_contexts: u,
            },
            ShapeSelection::Dynamic {
                provider: c,
                shape: y,
                child_contexts: v,
            },
        ) => {
            for operation in [&a.shape, &a.child_context, &c.shape, &c.child_context] {
                b.charge(
                    Resource::Work,
                    (operation.schema.package.len() + operation.name.len()) as u64 + 42,
                )?;
            }
            for shape in [x, y] {
                b.charge(Resource::Work, shape.kind.schema.package.len() as u64 + 42)?;
                for field in &shape.fields {
                    b.charge(Resource::Work, field.name.len() as u64 + 9)?;
                }
                for rule in &shape.selection_rules {
                    let size = match &rule.selector {
                        crate::package::StyleSelector::Field(v)
                        | crate::package::StyleSelector::Capture(v) => v.len(),
                        _ => 0,
                    };
                    b.charge(Resource::Work, size as u64 + 9)?;
                }
                for style in &shape.styles {
                    use crate::package::StyleSelector;
                    let size = match &style.selector {
                        StyleSelector::Field(v) | StyleSelector::Capture(v) => v.len(),
                        _ => 0,
                    };
                    b.charge(
                        Resource::Work,
                        (size + style.class.schema.package.len() + style.class.name.len()) as u64
                            + 43,
                    )?;
                }
            }
            for entry in u.iter().chain(v) {
                b.charge(
                    Resource::Work,
                    (entry.alias.len() + entry.category.len() + entry.mode.len()) as u64 + 1,
                )?;
            }
            a == c && x == y && u == v
        }
        _ => false,
    })
}
fn is_edit(d: &mut RenameDraft<'_, '_, '_, '_>, span: &Span) -> Result<bool, RenameError> {
    for edit in &d.candidate_edits {
        if same_source(span.snapshot_ref(), edit.span.snapshot_ref(), d.budget)?
            && span.start() == edit.span.start()
            && span.end() == edit.span.end()
        {
            return Ok(true);
        }
    }
    Ok(false)
}
fn atom(
    a: &NdfScalar,
    c: &NdfScalar,
    edited: bool,
    new_name: &str,
    b: &mut Budget,
) -> Result<bool, RenameError> {
    let size = |v: &NdfScalar| match v {
        NdfScalar::Text(v) => v.len() as u64,
        NdfScalar::Bytes(v) => v.len() as u64,
        NdfScalar::Integer(v) => v.as_bigint().bits().div_ceil(8),
        NdfScalar::Rational(v) => {
            v.numerator().as_bigint().bits().div_ceil(8) + v.denominator().bits().div_ceil(8)
        }
        _ => 1,
    };
    b.charge(
        Resource::Work,
        size(a)
            .saturating_add(size(c))
            .saturating_add(new_name.len() as u64),
    )?;
    Ok(
        a == c
            || (edited && matches!((a,c),(NdfScalar::Text(_),NdfScalar::Text(v)) if v==new_name)),
    )
}

use super::*;
use nepl3_core::facts::{Entity, NamespaceRef, ScopeId};

pub(super) fn verify(
    d: &mut RenameDraft<'_, '_, '_, '_>,
    p: &PreparedBindingRequest<'_, '_>,
    reply: &BoundBindingReply,
) -> Result<(), RenameError> {
    d.budget.poll()?;
    if p.key != reply.key()
        || p.key.profile_digest != d.original.key.profile_digest
        || p.key.execution_digest != d.original.key.execution_digest
        || p.key.request_digest != d.original.key.request_digest
        || p.options != d.original.options
        || p.limits != d.original.limits
    {
        return Err(RenameError::RequestMismatch);
    }
    let old = d
        .binding
        .for_source(&d.request.key, &d.request.source, d.budget)?
        .facts();
    let crate::binding::BindingOutcome::Complete(analysis) = &reply.reply().outcome else {
        return Err(BindingAccessError::Incomplete.into());
    };
    let new = analysis.facts();
    roots(d, old, new)?;
    super::shape::check(d, p, old, new)?;
    facts(d, old, new)?;
    let crate::binding::BindingOutcome::Complete(prior) = &d.binding.reply().outcome else {
        return Err(BindingAccessError::Incomplete.into());
    };
    for (a, c) in old.occurrences.iter().zip(&new.occurrences) {
        d.budget.charge(
            Resource::Work,
            (prior.result().open_inputs.len() + analysis.result().open_inputs.len()) as u64,
        )?;
        if prior.result().open_inputs.contains(&a.id)
            != analysis.result().open_inputs.contains(&c.id)
        {
            return Err(RenameError::ResolutionChanged);
        }
    }
    Ok(())
}
fn roots(
    d: &mut RenameDraft<'_, '_, '_, '_>,
    old: &FactSet,
    new: &FactSet,
) -> Result<(), RenameError> {
    // Being the target of one map never exempts an entire snapshot. Every byte
    // and URI, including unmapped tails, belongs to the speculative transaction.
    for (a, c) in [(old, new), (new, old)] {
        for source in &a.sources {
            let mut known = false;
            for other in &c.sources {
                d.budget.charge(
                    Resource::Work,
                    (source.identity().source.0.len() + other.identity().source.0.len()) as u64
                        + 42,
                )?;
                if source.identity().source == other.identity().source {
                    known = true;
                }
            }
            if !known {
                return Err(RenameError::RequestMismatch);
            }
        }
    }
    for source in &new.sources {
        let mut wanted = None;
        for candidate in d.sources.snapshots() {
            d.budget.charge(
                Resource::Work,
                (source.identity().source.0.len() + candidate.identity().source.0.len()) as u64
                    + 42,
            )?;
            if source.identity().source == candidate.identity().source
                && wanted.is_none_or(|v: &SourceSnapshot| {
                    v.identity().revision < candidate.identity().revision
                })
            {
                wanted = Some(candidate);
            }
        }
        let wanted = wanted.ok_or(RenameError::RequestMismatch)?;
        d.budget.charge(
            Resource::Work,
            (source.text().len() + wanted.text().len() + source.uri().len() + wanted.uri().len())
                as u64
                + 42,
        )?;
        if source != wanted {
            return Err(RenameError::RequestMismatch);
        }
    }
    Ok(())
}

fn scope(
    old: &FactSet,
    new: &FactSet,
    a: ScopeId,
    c: ScopeId,
    b: &mut Budget,
) -> Result<bool, RenameError> {
    b.charge(Resource::Work, (old.scopes.len() + new.scopes.len()) as u64)?;
    Ok(old.scopes.iter().position(|v| v.id == a) == new.scopes.iter().position(|v| v.id == c))
}
fn namespace(
    old: &FactSet,
    new: &FactSet,
    a: NamespaceRef,
    c: NamespaceRef,
    b: &mut Budget,
) -> Result<bool, RenameError> {
    let a = old
        .namespaces
        .get(a.0 as usize)
        .ok_or(RenameError::ResolutionChanged)?;
    let c = new
        .namespaces
        .get(c.0 as usize)
        .ok_or(RenameError::ResolutionChanged)?;
    b.charge(
        Resource::Work,
        (a.schema.package.len() + c.schema.package.len() + a.name.len() + c.name.len()) as u64 + 42,
    )?;
    Ok(a.schema == c.schema
        && a.name == c.name
        && a.policy == c.policy
        && scope(old, new, a.root, c.root, b)?)
}
fn entity_location(
    d: &mut RenameDraft<'_, '_, '_, '_>,
    old: &FactSet,
    new: &FactSet,
    a: &Entity,
    c: &Entity,
) -> Result<bool, RenameError> {
    if !scope(old, new, a.scope, c.scope, d.budget)?
        || !namespace(old, new, a.namespace, c.namespace, d.budget)?
    {
        return Ok(false);
    }
    for (a, c) in [(&a.selection, &c.selection), (&a.definition, &c.definition)] {
        match (a, c) {
            (Some(a), Some(c)) if spans(d, old, new, a, c)? => {}
            (None, None) => {}
            _ => return Ok(false),
        }
    }
    Ok(true)
}
fn facts(
    d: &mut RenameDraft<'_, '_, '_, '_>,
    old: &FactSet,
    new: &FactSet,
) -> Result<(), RenameError> {
    if old.scopes.len() != new.scopes.len()
        || old.entities.len() != new.entities.len()
        || old.occurrences.len() != new.occurrences.len()
        || old.namespaces.len() != new.namespaces.len()
    {
        return Err(RenameError::ResolutionChanged);
    }
    for (a, c) in old.scopes.iter().zip(&new.scopes) {
        match (a.parent, c.parent) {
            (Some(a), Some(c)) if scope(old, new, a, c, d.budget)? => {}
            (None, None) => {}
            _ => return Err(RenameError::ResolutionChanged),
        }
    }
    let mut entities = Vec::new();
    for a in &old.entities {
        let wanted = if a.id == d.entity {
            &d.request.new_name
        } else {
            &a.name
        };
        let mut found = None;
        for c in &new.entities {
            d.budget
                .charge(Resource::Work, (wanted.len() + c.name.len()) as u64 + 1)?;
            if c.name != *wanted || !entity_location(d, old, new, a, c)? {
                continue;
            }
            if found.is_some() {
                return Err(RenameError::Collision);
            }
            found = Some(c.id);
        }
        let id = found.ok_or(RenameError::ResolutionChanged)?;
        d.budget.charge(Resource::Work, entities.len() as u64)?;
        if entities.iter().any(|(_, v)| *v == id) {
            return Err(RenameError::Collision);
        }
        push(&mut entities, (a.id, id), d.budget)?;
    }
    let target = entities
        .iter()
        .find(|(id, _)| *id == d.entity)
        .map(|(_, id)| *id)
        .ok_or(RenameError::ResolutionChanged)?;
    let target = new
        .entities
        .iter()
        .find(|v| v.id == target)
        .ok_or(RenameError::ResolutionChanged)?;
    for other in &new.entities {
        d.budget.charge(
            Resource::Work,
            (target.name.len() + other.name.len()) as u64 + 1,
        )?;
        if target.id != other.id
            && target.scope == other.scope
            && target.namespace == other.namespace
            && target.name == other.name
        {
            return Err(RenameError::Collision);
        }
    }
    // Correspondence uses source geometry, lexical placement, role and issuance
    // order, not equality of opaque EntityId/OccurrenceId numbers.
    for (a, c) in old.occurrences.iter().zip(&new.occurrences) {
        if a.role != c.role
            || !scope(old, new, a.scope, c.scope, d.budget)?
            || !namespace(old, new, a.namespace, c.namespace, d.budget)?
            || !spans(d, old, new, &a.span, &c.span)?
        {
            return Err(RenameError::ResolutionChanged);
        }
        let renamed = matches!(a.resolution,ReferenceResolution::Resolved(id) if id==d.entity);
        let wanted = if renamed {
            &d.request.new_name
        } else {
            &a.name
        };
        d.budget
            .charge(Resource::Work, (wanted.len() + c.name.len()) as u64)?;
        if *wanted != c.name {
            return Err(RenameError::ResolutionChanged);
        }
        if !resolution(&a.resolution, &c.resolution, &entities, d.budget)? {
            return Err(RenameError::ResolutionChanged);
        }
    }
    Ok(())
}
fn resolution(
    a: &ReferenceResolution,
    c: &ReferenceResolution,
    ids: &[(EntityId, EntityId)],
    b: &mut Budget,
) -> Result<bool, RenameError> {
    let mapped = |id: EntityId, b: &mut Budget| -> Result<Option<EntityId>, RenameError> {
        b.charge(Resource::Work, ids.len() as u64)?;
        Ok(ids.iter().find(|(a, _)| *a == id).map(|(_, c)| *c))
    };
    Ok(match (a, c) {
        (ReferenceResolution::Resolved(a), ReferenceResolution::Resolved(c)) => {
            mapped(*a, b)? == Some(*c)
        }
        (ReferenceResolution::Unresolved(a), ReferenceResolution::Unresolved(c)) => {
            b.charge(Resource::Work, (a.len() + c.len()) as u64)?;
            a == c
        }
        (ReferenceResolution::Ambiguous(a), ReferenceResolution::Ambiguous(c)) => {
            if a.len() != c.len() {
                return Ok(false);
            }
            for (a, c) in a.iter().zip(c) {
                if mapped(*a, b)? != Some(*c) {
                    return Ok(false);
                }
            }
            true
        }
        (ReferenceResolution::Deferred(a), ReferenceResolution::Deferred(c)) => {
            use nepl3_core::value::TypedValue;
            if a.len() != c.len() {
                return Ok(false);
            }
            for (a, c) in a.iter().zip(c) {
                let (schema_a, schema_c, name_a, name_c, variant_a, variant_c, fields_a, fields_c) =
                    match (a, c) {
                        (TypedValue::Record(a), TypedValue::Record(c)) => (
                            &a.schema, &c.schema, &a.kind, &c.kind, "", "", &a.fields, &c.fields,
                        ),
                        (TypedValue::Variant(a), TypedValue::Variant(c)) => (
                            &a.schema,
                            &c.schema,
                            &a.type_name,
                            &c.type_name,
                            a.variant.as_str(),
                            c.variant.as_str(),
                            &a.fields,
                            &c.fields,
                        ),
                        _ => return Ok(false),
                    };
                b.charge(
                    Resource::Work,
                    (schema_a.package.len()
                        + schema_c.package.len()
                        + name_a.len()
                        + name_c.len()
                        + variant_a.len()
                        + variant_c.len()) as u64
                        + 42,
                )?;
                if schema_a != schema_c
                    || name_a != name_c
                    || variant_a != variant_c
                    || fields_a.len() != fields_c.len()
                {
                    return Ok(false);
                }
                for (a, c) in fields_a.iter().zip(fields_c) {
                    if !a.equal_with_budget(c, b)? {
                        return Ok(false);
                    }
                }
            }
            true
        }
        _ => false,
    })
}
pub(super) fn spans(
    d: &mut RenameDraft<'_, '_, '_, '_>,
    old: &FactSet,
    new: &FactSet,
    a: &Span,
    c: &Span,
) -> Result<bool, RenameError> {
    if same_source(a.snapshot_ref(), c.snapshot_ref(), d.budget)?
        && a.start() == c.start()
        && a.end() == c.end()
    {
        return Ok(true);
    }
    // Broad covers can include mapped and unmapped bytes. The draft already
    // derived the exact edits for each declared snapshot, so compare their own
    // byte geometry before attempting a cross-source correspondence.
    for candidate in d.sources.snapshots() {
        d.budget.charge(
            Resource::Work,
            (candidate.identity().source.0.len() + a.snapshot_ref().source.0.len()) as u64 + 42,
        )?;
        if candidate.identity().source == a.snapshot_ref().source
            && same_source(candidate.identity(), c.snapshot_ref(), d.budget)?
        {
            return Ok(
                shift(a, a.start(), &d.candidate_edits, d.budget)? == c.start()
                    && shift(a, a.end(), &d.candidate_edits, d.budget)? == c.end(),
            );
        }
    }
    let a = root(a, old, d.budget)?;
    let c = root(c, new, d.budget)?;
    let Some(snapshot) = d.sources.latest(&a.snapshot_ref().source) else {
        return Ok(false);
    };
    if !same_source(snapshot.identity(), c.snapshot_ref(), d.budget)? {
        return Ok(false);
    }
    Ok(shift(&a, a.start(), &d.edits, d.budget)? == c.start()
        && shift(&a, a.end(), &d.edits, d.budget)? == c.end())
}
fn shift(span: &Span, point: u64, edits: &[TextEdit], b: &mut Budget) -> Result<u64, RenameError> {
    let mut result = i128::from(point);
    for edit in edits {
        if !same_source(span.snapshot_ref(), edit.span.snapshot_ref(), b)? {
            continue;
        }
        if edit.span.start() < point && point < edit.span.end() {
            return Err(RenameError::ShapeChanged);
        }
        if edit.span.end() <= point {
            result +=
                edit.replacement.len() as i128 - i128::from(edit.span.end() - edit.span.start());
        }
    }
    u64::try_from(result).map_err(|_| RenameError::ShapeChanged)
}
fn root(span: &Span, facts: &FactSet, b: &mut Budget) -> Result<Span, RenameError> {
    let mut span = copy_span(span, b)?;
    let mut seen = Vec::new();
    loop {
        b.observe_depth(seen.len() as u64 + 1)?;
        for old in &seen {
            let old: &Span = old;
            if same_source(old.snapshot_ref(), span.snapshot_ref(), b)?
                && old.start() == span.start()
                && old.end() == span.end()
            {
                return Err(OriginError::Cycle.into());
            }
        }
        push(&mut seen, copy_span(&span, b)?, b)?;
        let mut projected =
            super::mapping::project(&span, &facts.source_maps, &facts.sources, true, b)?;
        if projected.len() > 1 {
            return Err(RenameError::RenameNotInvertible);
        }
        let Some(next) = projected.pop() else {
            return Ok(span);
        };
        span = next;
    }
}
